import itertools

def is_colorful(m, n, w):
    # n flavors, window size w, length m
    for seq in itertools.product(range(1, n + 1), repeat=m):
        all_windows_ok = True
        for i in range(m):
            window = []
            for j in range(w):
                window.append(seq[(i + j) % m])
            if len(set(window)) < n:
                all_windows_ok = False
                break
        if all_windows_ok:
            return True
    return False

