def is_colorful(m, n, w):
    # For larger m, itertools.product is too slow.
    # We can use backtracking/DFS to check if a sequence exists.
    def backtrack(curr_seq):
        if len(curr_seq) == m:
            # Check the wrap-around windows
            for i in range(m - w + 1, m):
                window = []
                for j in range(w):
                    window.append(curr_seq[(i + j) % m])
                if len(set(window)) < n:
                    return False
            return True

        for flavor in range(1, n + 1):
            new_seq = curr_seq + [flavor]
            # Check the window that just finished
            if len(new_seq) >= w:
                window = new_seq[-w:]
                if len(set(window)) < n:
                    continue
            if backtrack(new_seq):
                return True
        return False

    return backtrack([])

